import { AfmError } from './errors.js'
import { type SchemaInput, toStructuredSchema } from './schema.js'

export interface ToolContext {
  /** Aborted when the generation is cancelled or the tool times out. */
  signal: AbortSignal
  sessionId: string
}

/**
 * A function the model may call. Arguments are generated by the model to match
 * `parameters`, validated, and passed to `execute`. The return value goes back to the
 * model: strings as they are, anything else as JSON.
 */
export interface Tool<Args = unknown> {
  /** `^[a-zA-Z_][a-zA-Z0-9_]{0,63}$` */
  name: string
  /** Tells the model when to use the tool. */
  description: string
  /** Object schema of the arguments (JSON Schema or `zodSchema()`). */
  parameters: SchemaInput<Args>
  includeSchemaInInstructions?: boolean
  /** Default 60 000 ms. */
  timeoutMs?: number
  execute(args: Args, context: ToolContext): unknown
}

/** Identity helper that infers the argument type from `parameters`. */
export function tool<Args>(definition: Tool<Args>): Tool<Args> {
  return definition
}

/** Wire format for `session/create`. */
export function toolDefinition(t: Tool<unknown>) {
  return {
    name: t.name,
    description: t.description,
    parameters: toStructuredSchema(t.parameters).jsonSchema,
    ...(t.includeSchemaInInstructions === undefined
      ? {}
      : { includeSchemaInInstructions: t.includeSchemaInInstructions }),
  }
}

const DEFAULT_TOOL_TIMEOUT_MS = 60_000

/** Runs a tool for a `tool/call` request. Errors become the error reply to the sidecar. */
export async function runTool(
  t: Tool<unknown>,
  rawArguments: unknown,
  context: { signal: AbortSignal; sessionId: string },
): Promise<{ output: string }> {
  const args = toStructuredSchema(t.parameters).parse(rawArguments)
  const timeoutMs = t.timeoutMs ?? DEFAULT_TOOL_TIMEOUT_MS
  const timeout = AbortSignal.timeout(timeoutMs)
  const signal = AbortSignal.any([context.signal, timeout])

  // Settle as soon as the signal aborts, even if `execute` ignores it.
  let onAbort = () => {}
  const aborted = new Promise<never>((_, reject) => {
    onAbort = () =>
      reject(
        timeout.aborted
          ? new AfmError(`Tool '${t.name}' timed out after ${timeoutMs} ms`, { type: 'toolTimeout' })
          : new AfmError(`Tool '${t.name}' was cancelled`, { type: 'cancelled' }),
      )
    if (signal.aborted) onAbort()
    else signal.addEventListener('abort', onAbort, { once: true })
  })
  try {
    const result = await Promise.race([
      Promise.resolve().then(() => t.execute(args, { signal, sessionId: context.sessionId })),
      aborted,
    ])
    return { output: typeof result === 'string' ? result : JSON.stringify(result ?? null) }
  } finally {
    signal.removeEventListener('abort', onAbort)
    aborted.catch(() => {})
  }
}
